/// Individual custom sticker with labels for search
struct CustomSticker: Identifiable, Codable, Hashable {
    var id = UUID()
    let name: String
    let labels: [String]
    
    init(name: String, labels: [String] = []) {
        self.name = name
        self.labels = labels
    }
}

